def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    edges = s.get('neighbors') or []
    nearest = [7.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and occ[j] > 0 and d is not None and 0 < d <= 6:
            nearest[i] = min(nearest[i], d)
    values = [0.0] * n
    counts = [0.0] * n
    for edge in edges:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6 and d <= 1.3 * nearest[i]:
            if en[i] is not None and en[j] is not None:
                values[i] += occ[j] * (en[j] - en[i])
                counts[i] += occ[j]
    weight = sum(occ[i] for i in range(n) if counts[i] > 0)
    if weight <= 0:
        return 0.0
    mean = sum(occ[i] * values[i] / counts[i] for i in range(n) if counts[i] > 0) / weight
    variance = sum(occ[i] * (values[i] / counts[i] - mean) ** 2 for i in range(n) if counts[i] > 0) / weight
    return sqrt(max(0.0, variance))

